# ExportDecompiled.py
#@category GD 2.209
# Ghidra Jython 2.7 script; invoke through analyzeHeadless -postScript.
# Arguments: output-directory [max-functions(0=all)] [timeout-seconds]
# Writes local C-like pseudocode generated by Ghidra, not compilable source.

import os
import re
import json
import time
from ghidra.app.decompiler import DecompInterface

args = getScriptArgs()
if not args:
    raise RuntimeError('usage: ExportDecompiled.py <output-dir> [max-functions] [timeout-seconds]')

out_dir = os.path.abspath(args[0])
max_functions = int(args[1]) if len(args) > 1 else 0
seconds_per_function = int(args[2]) if len(args) > 2 else 60
if max_functions < 0 or seconds_per_function < 1:
    raise RuntimeError('invalid limit or timeout')
if not os.path.isdir(out_dir):
    os.makedirs(out_dir)

interface = DecompInterface()
interface.setSimplificationStyle('decompile')
if not interface.openProgram(currentProgram):
    raise RuntimeError('Ghidra decompiler could not open program')

index_path = os.path.join(out_dir, 'manifest.jsonl')
processed = 0
exported = 0
failed = 0
skipped = 0

def write_index(record):
    fp = open(index_path, 'ab')
    try:
        fp.write((json.dumps(record, ensure_ascii=True) + '\n').encode('ascii'))
    finally:
        fp.close()

try:
    manager = currentProgram.getFunctionManager()
    for fn in manager.getFunctions(True):
        if monitor.isCancelled():
            break
        if fn.isExternal():
            continue
        if max_functions and processed >= max_functions:
            break
        processed += 1
        va = str(fn.getEntryPoint())
        name = str(fn.getName())
        safe = re.sub(r'[^a-zA-Z0-9_.-]', '_', name)[:70]
        filename = 'func_%s_%s.c' % (va, safe)
        path = os.path.join(out_dir, filename)
        if os.path.isfile(path):
            skipped += 1
            continue
        record = {'address': va, 'symbol': name, 'file': filename, 'status': 'error'}
        try:
            result = interface.decompileFunction(fn, seconds_per_function, monitor)
            if not result.decompileCompleted():
                raise RuntimeError(str(result.getErrorMessage()))
            decomp = result.getDecompiledFunction()
            if decomp is None:
                raise RuntimeError('no decompiled result')
            code = unicode(decomp.getC())
            header = u'/* Research pseudocode only; address 0x%s, symbol %s.\n' % (va, name)
            header += u' * Recovered type names and function signatures can be incorrect. */\n\n'
            fp = open(path, 'wb')
            try:
                fp.write((header + code).encode('utf-8'))
            finally:
                fp.close()
            record['status'] = 'ok'
            exported += 1
        except Exception as exc:
            failed += 1
            record['reason'] = unicode(exc)[:350]
        write_index(record)
        if processed % 100 == 0:
            print('processed=%d exported=%d skipped=%d failed=%d' % (processed, exported, skipped, failed))
finally:
    interface.dispose()

print('EXPORT COMPLETE processed=%d exported=%d skipped=%d failed=%d output=%s' %
      (processed, exported, skipped, failed, out_dir))
